package com.bayram.promarksaha;
import android.content.*;import android.graphics.*;import android.view.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;
public class FieldMapView extends View { private GnssFix fix;private SurveyPoint a,b;private final Paint p=new Paint(3);private final Map<String,Bitmap> tiles=new ConcurrentHashMap<>();private final Set<String> loading=ConcurrentHashMap.newKeySet();private final ExecutorService io=Executors.newFixedThreadPool(6);private int zoom=19;public FieldMapView(Context c){super(c);p.setAntiAlias(true);setBackgroundColor(0xff202020);}public void setFix(GnssFix f){fix=f;invalidate();}public void setLine(SurveyPoint x,SurveyPoint y){a=x;b=y;invalidate();}
 protected void onDraw(Canvas c){super.onDraw(c);if(fix==null||Double.isNaN(fix.lat)){p.setColor(Color.LTGRAY);p.setTextSize(28);p.setTextAlign(Paint.Align.CENTER);c.drawText("PROMARK KONUMU BEKLENIYOR",getWidth()/2f,getHeight()/2f,p);return;}drawTiles(c,fix.lat,fix.lon);if(a!=null&&b!=null){PointF pa=screen(a.lat,a.lon,fix.lat,fix.lon),pb=screen(b.lat,b.lon,fix.lat,fix.lon);p.setColor(0xffff8a00);p.setStrokeWidth(7);c.drawLine(pa.x,pa.y,pb.x,pb.y,p);}PointF m=new PointF(getWidth()/2f,getHeight()/2f);p.setColor(0xffe53935);c.drawCircle(m.x,m.y,13,p);p.setColor(Color.WHITE);p.setStrokeWidth(3);c.drawLine(m.x-22,m.y,m.x+22,m.y,p);c.drawLine(m.x,m.y-22,m.x,m.y+22,p);p.setTextAlign(Paint.Align.LEFT);p.setTextSize(20);p.setColor(Color.WHITE);c.drawText("UYDU",12,getHeight()-16,p);}
 private void drawTiles(Canvas c,double lat,double lon){double[] w=world(lat,lon,zoom);int ts=256,cx=(int)Math.floor(w[0]/ts),cy=(int)Math.floor(w[1]/ts);for(int dx=-2;dx<=2;dx++)for(int dy=-2;dy<=2;dy++){int tx=cx+dx,ty=cy+dy;String k=zoom+"_"+tx+"_"+ty;Bitmap bm=tiles.get(k);float l=(float)(getWidth()/2+(tx*ts-w[0])),t=(float)(getHeight()/2+(ty*ts-w[1]));if(bm!=null)c.drawBitmap(bm,l,t,p);else load(k,zoom,tx,ty);}}
 private void load(String k,int z,int x,int y){if(!loading.add(k))return;io.submit(()->{try{File d=new File(getContext().getCacheDir(),"satellite");d.mkdirs();File f=new File(d,k+".jpg");Bitmap bm;if(f.exists())bm=BitmapFactory.decodeFile(f.getAbsolutePath());else{HttpURLConnection h=(HttpURLConnection)new URL("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/"+z+"/"+y+"/"+x).openConnection();h.setRequestProperty("User-Agent","ProMarkSaha/0.2");h.setConnectTimeout(2200);h.setReadTimeout(3200);try(InputStream in=h.getInputStream();FileOutputStream out=new FileOutputStream(f)){byte[] q=new byte[16384];int n;while((n=in.read(q))>0)out.write(q,0,n);}bm=BitmapFactory.decodeFile(f.getAbsolutePath());}if(bm!=null){tiles.put(k,bm);postInvalidate();}}catch(Exception ignored){}finally{loading.remove(k);}});}
 private PointF screen(double lat,double lon,double clat,double clon){double[] a=world(lat,lon,zoom),b=world(clat,clon,zoom);return new PointF((float)(getWidth()/2+a[0]-b[0]),(float)(getHeight()/2+a[1]-b[1]));}private static double[] world(double lat,double lon,int z){double n=Math.pow(2,z)*256.0,x=(lon+180)/360*n,s=Math.sin(Math.toRadians(lat)),y=(0.5-Math.log((1+s)/(1-s))/(4*Math.PI))*n;return new double[]{x,y};}}
